// Command generate derives transport adapters and policies from the public descriptor.
package main

import (
	"bytes"
	"fmt"
	"go/format"
	"os"

	watchpb "github.com/drasi-project/temporal-drasi/contracts/watch/v1"
	"google.golang.org/protobuf/proto"
)

func main() {
	var out bytes.Buffer
	out.WriteString(`// Code generated by go run ./internal/generate. DO NOT EDIT.

package validation

import (
    "context"

    watchpb "github.com/drasi-project/temporal-drasi/contracts/watch/v1"
    "github.com/grpc-ecosystem/grpc-gateway/v2/runtime"
)

// Policy returns the backend authorization boundary for a public RPC.
func Policy(fullMethod string) (MethodPolicy, bool) {
    switch fullMethod {
`)
	services := watchpb.File_drasi_watch_v1_service_proto.Services()
	for i := 0; i < services.Len(); i++ {
		service := services.Get(i)
		for j := 0; j < service.Methods().Len(); j++ {
			method := service.Methods().Get(j)
			access := proto.GetExtension(method.Options(), watchpb.E_Access).(watchpb.Access)
			if access == watchpb.Access_ACCESS_UNSPECIFIED {
				panic("missing method access: " + method.FullName())
			}
			mutation := access == watchpb.Access_ACCESS_NAMESPACE_WRITE || access == watchpb.Access_ACCESS_CLUSTER_ADMIN
			fmt.Fprintf(&out, "case %q: return MethodPolicy{Access: watchpb.Access_%s, Mutation: %t}, true\n",
				"/"+string(service.FullName())+"/"+string(method.Name()), access.String(), mutation)
		}
	}
	out.WriteString("default: return MethodPolicy{}, false\n}\n}\n")
	for i := 0; i < services.Len(); i++ {
		service := services.Get(i)
		name := string(service.Name())
		wrapper := "validated" + name
		fmt.Fprintf(&out, `
// Wrap%s validates requests for direct calls and in-process gateway dispatch.
// Authorization must still be enforced by the application before dispatch.
func Wrap%s(server watchpb.%sServer) watchpb.%sServer {
    return &%s{%sServer: server}
}

type %s struct { watchpb.%sServer }

// Register%sHandlerServer registers a validating in-process HTTP gateway.
// This does not run gRPC authorization interceptors.
func Register%sHandlerServer(ctx context.Context, mux *runtime.ServeMux, server watchpb.%sServer) error {
    return watchpb.Register%sHandlerServer(ctx, mux, Wrap%s(server))
}
`, name, name, name, name, wrapper, name, wrapper, name, name, name, name, name, name)
		for j := 0; j < service.Methods().Len(); j++ {
			method := service.Methods().Get(j)
			fmt.Fprintf(&out, `
func (server *%s) %s(ctx context.Context, request *watchpb.%s) (*watchpb.%s, error) {
    if err := ValidateRequest(request); err != nil { return nil, err }
    return server.%sServer.%s(ctx, request)
}
`, wrapper, method.Name(), method.Input().Name(), method.Output().Name(), name, method.Name())
		}
	}
	formatted, err := format.Source(out.Bytes())
	if err != nil {
		panic(err)
	}
	if err := os.MkdirAll("validation", 0o755); err != nil {
		panic(err)
	}
	if err := os.WriteFile("validation/adapters.gen.go", formatted, 0o644); err != nil {
		panic(err)
	}
}
